from abc import ABC, abstractmethod
import numpy as np


class BaseLayer(ABC):
    def __init__(self):
        pass

    def __call__(self, x, *args, **kwargs):
        return self.forward(x, *args, **kwargs)

    @abstractmethod
    def forward(self, x):
        raise NotImplementedError
