import numpy as np


def zero_pad(x, pad):
    x = np.asarray(x, dtype=np.float64)
    if pad == 0:
        return x.copy()
    return np.pad(x, ((0, 0), (pad, pad), (pad, pad), (0, 0)), mode='constant', constant_values=0.0).astype(np.float64)


def get_output_shape(input_shape, kernel_size, stride, padding, dilation=1):
    h, w = input_shape

    def _out(i):
        return (i + 2 * padding - dilation * (kernel_size - 1) - 1) // stride + 1

    return (int(_out(h)), int(_out(w)))
