import numpy as np
from .base import BaseLayer


class _Pool2D(BaseLayer):
    def __init__(self, kernel_size, stride=None):
        super().__init__()
        self.kernel_size = int(kernel_size)
        self.stride = int(stride) if stride is not None else self.kernel_size

    def _windows(self, x):
        x = np.asarray(x, dtype=np.float64)
        N, H, W, C = x.shape
        k, s = self.kernel_size, self.stride
        oh = (H - k) // s + 1
        ow = (W - k) // s + 1
        for i in range(k):
            for j in range(k):
                yield x[:, i:i + s * (oh - 1) + 1:s, j:j + s * (ow - 1) + 1:s, :]


class MaxPool2D(_Pool2D):
    def forward(self, x):
        out = None
        for patch in self._windows(x):
            out = patch.copy() if out is None else np.maximum(out, patch)
        return out.astype(np.float64)


class AvgPool2D(_Pool2D):
    def forward(self, x):
        total = None
        for patch in self._windows(x):
            total = patch.copy() if total is None else total + patch
        return (total / (self.kernel_size * self.kernel_size)).astype(np.float64)
